def stringConversion(X, Y):
    n, m = len(X), len(Y)
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    # Base case: empty string to empty string is always true
    dp[0][0] = True

    # Fill the dp table for empty string X
    for j in range(1, m + 1):
        dp[0][j] = dp[0][j - 1] and Y[j - 1].isupper()

    # Fill the dp table for non-empty string X
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif X[i - 1].islower():
                if X[i - 1].upper() == Y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = False

    return 1 if dp[n][m] else 0

